import random
import re

MAX_STONES = 10**17
COUNT_BOUNDS = (
    2, 5, 15, 52, 203, 877, 4140, 21147, 115975, 678570, 4213597,
)
SMALL_CASES = (
    (1, 1),
    (1, 2),
    (100000000000000000, 100000000000000000),
    (1, 100000000000000000),
    (2, 5, 7),
    (1, 1, 2, 2),
    (1, 2, 4, 8, 16, 32),
    (3, 3, 3, 3, 3, 3),
    (71, 74, 45, 34, 31, 60),
)


def _bounded_positive(token: str, upper: int) -> int | None:
    if re.fullmatch(r"\+?[0-9]+", token) is None:
        return None
    digits = token.lstrip("+").lstrip("0")
    if not digits or len(digits) > len(str(upper)):
        return None
    value = int(digits)
    return value if value <= upper else None


def _parse_input(inp: str) -> list[int] | None:
    tokens = inp.split()
    if not tokens:
        return None
    size = _bounded_positive(tokens[0], 12)
    if size is None or size < 2 or len(tokens) != size + 1:
        return None

    values = []
    for token in tokens[1:]:
        value = _bounded_positive(token, MAX_STONES)
        if value is None:
            return None
        values.append(value)
    return values


def _format_input(values: list[int] | tuple[int, ...]) -> str:
    return f"{len(values)}\n" + " ".join(map(str, values)) + "\n"


def _xor(values: list[int] | tuple[int, ...]) -> int:
    result = 0
    for value in values:
        result ^= value
    return result


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = []
    for index in range(n):
        if index < len(SMALL_CASES):
            values = SMALL_CASES[index]
        else:
            size = rng.randint(2, 6)
            upper = (4, 255, MAX_STONES)[index % 3]
            values = [rng.randint(1, upper) for _ in range(size)]
        cases.append(_format_input(values))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    wide_values = rng.sample(range(MAX_STONES // 2, MAX_STONES + 1), 12)
    overlapping_values = [MAX_STONES] * 6
    overlapping_values.extend(MAX_STONES - (1 << bit) for bit in range(6))
    rng.shuffle(overlapping_values)
    return [_format_input(wide_values), _format_input(overlapping_values)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    values = _parse_input(inp)
    if values is None:
        return [("POST-1", "Input violates the token count or value bounds.")]

    tokens = out.split()
    if len(tokens) != 1 or re.fullmatch(r"[+-]?[0-9]+", tokens[0]) is None:
        return [("POST-2", "Expected exactly one decimal integer token.")]

    total = sum(values)
    upper = min(COUNT_BOUNDS[len(values) - 2], total // 2 + 1)
    count = _bounded_positive(tokens[0], upper)
    if count is None:
        return [("POST-4", f"The count must be between 1 and {upper}.")]

    if _xor(values) == total and count != 1:
        return [("POST-5", "The initial XOR equals the total, so the count must be 1.")]
    if _xor(values) != total and count < 2:
        return [("POST-5", "The initial XOR and the all-in-one-bag XOR differ.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index in range(n):
        size = rng.randint(2, 12)
        if index % 2 == 0:
            values = rng.sample(range(1, MAX_STONES + 1), size)
            offset = rng.randrange(1, size)
            transformed = values[offset:] + values[:offset]
            post_id = "POST-6"
        else:
            factor = 1 << rng.randint(1, 56)
            values = [rng.randint(1, MAX_STONES // factor) for _ in range(size)]
            transformed = [value * factor for value in values]
            post_id = "POST-7"
        pairs.append((post_id, "equal", _format_input(values), _format_input(transformed)))
    return pairs


def reference_small(inp: str) -> str | None:
    values = _parse_input(inp)
    if values is None or len(values) > 6:
        return None

    initial = tuple(values)
    seen = {initial}
    pending = [initial]
    outcomes = set()

    while pending:
        state = pending.pop()
        outcomes.add(_xor(state))
        for source, stones in enumerate(state):
            if stones == 0:
                continue
            for destination in range(len(state)):
                if source == destination:
                    continue
                moved = list(state)
                moved[source] = 0
                moved[destination] += stones
                next_state = tuple(moved)
                if next_state not in seen:
                    seen.add(next_state)
                    pending.append(next_state)

    return f"{len(outcomes)}\n"
